import { useState } from "react";
import api from "../services/ApiService";
function Transfer() {
  const [transfer, setTransfer] = useState({
    fromaccno: "",
    toaccno: "",
    amount: "",
  });

  const handleChange = (e) => {
    setTransfer({
      ...transfer,
      [e.target.name]: e.target.value,
    });
  };

  const transferMoney = async (e) => {
    e.preventDefault();

    const response = await api.put(
      "/accounts/transfer",
      {},
      {
        params: {
          fromaccno: transfer.fromaccno,
          toaccno: transfer.toaccno,
          amount: transfer.amount,
        },
      },
    );

    //     try {
    //         const response = await api.put(
    // `/accounts/transfer?fromaccno=${transfer.fromaccno}&toaccno=${transfer.toaccno}&amount=${trans fer.amount}`
    //         );
    //         alert(response.data);
    //         setTransfer({
    //             fromaccno: "",
    //             toaccno: "",
    //             amount: ""
    //         });
    //     } catch (error) {
    //         if (error.response) {
    //             alert(error.response.data);
    //         } else {
    //             alert("Server Not Running");
    //         }
    //     }
  };

  return (
    <div style={{ textAlign: "center", marginTop: "30px" }}>
      <h2>Transfer Money</h2>
      <form onSubmit={transferMoney}>
        <input
          type="text"
          name="fromaccno"
          placeholder="Sender Account Number"
          value={transfer.fromaccno}
          onChange={handleChange}
          required
        />
        <br />
        <br />
        <input
          type="text"
          name="toaccno"
          placeholder="Receiver Account Number"
          value={transfer.toaccno}
          onChange={handleChange}
          required
        />
        <br />
        <br />{" "}
        <input
          type="number"
          name="amount"
          placeholder="Enter Amount"
          value={transfer.amount}
          onChange={handleChange}
          required
        />{" "}
        <br />
        <br /> <button type="submit"> Transfer </button>{" "}
      </form>{" "}
    </div>
  );
}

export default Transfer;
